// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(w http.ResponseWriter, r *http.Request)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(w http.ResponseWriter, r *http.Request)
	// 分页备份目录
	// (GET /v1/backups)
	ListBackups(w http.ResponseWriter, r *http.Request, params ListBackupsParams)
	// 建立备份操作
	// (POST /v1/backups)
	CreateBackup(w http.ResponseWriter, r *http.Request, params CreateBackupParams)
	// 读取备份描述
	// (GET /v1/backups/{backupId})
	ReadBackup(w http.ResponseWriter, r *http.Request, backupId string, params ReadBackupParams)
	// 下载可移植完整备份
	// (GET /v1/backups/{backupId}/download)
	StreamPortableBackup(w http.ResponseWriter, r *http.Request, backupId string, params StreamPortableBackupParams)
	// 下载私有备份授权
	// (POST /v1/backups/{backupId}:download)
	AuthorizeBackupDownload(w http.ResponseWriter, r *http.Request, backupId string, params AuthorizeBackupDownloadParams)
	// 恢复入口接收完整备份
	// (POST /v1/backups:import)
	ImportPortableBackup(w http.ResponseWriter, r *http.Request, params ImportPortableBackupParams)
	// 取得本域快照安全截点
	// (POST /v1/barriers)
	AcquireBarrier(w http.ResponseWriter, r *http.Request, params AcquireBarrierParams)
	// 解除本域维护
	// (POST /v1/barriers/{barrierId}:release)
	ReleaseBarrier(w http.ResponseWriter, r *http.Request, barrierId string, params ReleaseBarrierParams)
	// 设置远程同步目标
	// (PUT /v1/git-remote)
	ConfigureRemote(w http.ResponseWriter, r *http.Request, params ConfigureRemoteParams)
	// 每日本地备份
	// (PUT /v1/local-backup-schedule)
	ScheduleLocalBackup(w http.ResponseWriter, r *http.Request, params ScheduleLocalBackupParams)
	// 建立data git版本镜像
	// (POST /v1/mirrors)
	BuildMirror(w http.ResponseWriter, r *http.Request, params BuildMirrorParams)
	// 读取镜像与远程同步状态
	// (GET /v1/mirrors/status)
	ReadMirrorStatus(w http.ResponseWriter, r *http.Request)
	// 显式远程fast-forward同步
	// (POST /v1/mirrors/{mirrorId}:sync)
	SyncMirror(w http.ResponseWriter, r *http.Request, mirrorId string, params SyncMirrorParams)
	// 建立完整恢复
	// (POST /v1/restores)
	CreateRestore(w http.ResponseWriter, r *http.Request, params CreateRestoreParams)
	// 向暂存中的域提供其归档
	// (GET /v1/restores/{restoreId}/archives/{owner})
	ServeRestoreArchive(w http.ResponseWriter, r *http.Request, restoreId string, owner string, params ServeRestoreArchiveParams)
	// 读取恢复进度
	// (GET /v1/restores/{restoreId}/progress)
	ReadRestoreProgress(w http.ResponseWriter, r *http.Request, restoreId string, params ReadRestoreProgressParams)
	// 切换前撤销或切换后整体换回
	// (POST /v1/restores/{restoreId}:abort)
	AbortRestore(w http.ResponseWriter, r *http.Request, restoreId string, params AbortRestoreParams)
	// 清理恢复保留目录
	// (POST /v1/restores/{restoreId}:cleanup)
	CleanupRestore(w http.ResponseWriter, r *http.Request, restoreId string, params CleanupRestoreParams)
	// 继续中断恢复
	// (POST /v1/restores/{restoreId}:continue)
	ContinueRestore(w http.ResponseWriter, r *http.Request, restoreId string, params ContinueRestoreParams)
	// 全域恢复预检
	// (POST /v1/restores:validate)
	ValidateRestore(w http.ResponseWriter, r *http.Request, params ValidateRestoreParams)
	// 读取备份与镜像设置
	// (GET /v1/settings)
	ReadProtectionSettings(w http.ResponseWriter, r *http.Request)
	// 初始化向导从完整备份恢复
	// (POST /v1/setup:restore)
	RestoreDuringSetup(w http.ResponseWriter, r *http.Request, params RestoreDuringSetupParams)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(w http.ResponseWriter, r *http.Request, snapshotId Identifier, params ReadSnapshotArchiveParams)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(w http.ResponseWriter, r *http.Request, params DiscardSnapshotParams)
	// 导出本域操作目录快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(w http.ResponseWriter, r *http.Request, params ExportSnapshotParams)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(w http.ResponseWriter, r *http.Request, params StageSnapshotParams)
}

